import {mount} from 'cypress/react';
import {Harness,stubRpc,board,issue} from '../support/harness';
import {PriorityBadge} from '../../client/priority-badge';
for(const background of ['#242932','#ffffff'])it(`priority pills on ${background} → distinct colors and readable labels`,()=>{
 cy.viewport(320,700);
 mount(<div style={{background,padding:16,width:260,display:'flex',flexDirection:'column',gap:8}}>
  {['Highest','High','Medium','Low','Lowest','Custom priority'].map(priority=><PriorityBadge key={priority} priority={priority}/>)}
 </div>);
 for(const label of ['Highest','High','Medium','Low','Lowest','Custom priority']){
  cy.get(`[aria-label="Priority: ${label}"]`).should('be.visible').and('contain.text',label).should($el=>{
   const style=getComputedStyle($el[0]);
   expect(style.backgroundColor).not.eq('rgba(0, 0, 0, 0)');
   expect(style.borderRadius).eq('999px');
   expect($el[0].getBoundingClientRect().right).at.most(320);
  });
 }
 cy.get('[aria-label="Priority: High"]').should('have.css','background-color','rgb(73, 40, 32)');
 cy.get('[aria-label="Priority: Medium"]').should('have.css','background-color','rgb(68, 52, 20)');
 cy.get('[aria-label="Priority: Low"]').should('have.css','background-color','rgb(23, 54, 92)');
});

it('card borders match priority pills and retain their color when selected',()=>{
 cy.viewport(1440,900);stubRpc();
 const priorities=['Highest','High','Medium','Low','Lowest'];
 cy.intercept('POST','/__rpc/board.read',{...board,issues:priorities.map((priority,i)=>({...issue(`TEST-${i+1}`),priority}))});
 mount(<Harness mode="panel"/>);
 const colors=['rgb(255, 139, 115)','rgb(255, 139, 115)','rgb(255, 191, 71)','rgb(112, 173, 255)','rgb(112, 173, 255)'];
 priorities.forEach((priority,i)=>{
  cy.get(`[data-testid="issue-card-TEST-${i+1}"]`).should('have.css','border-left-color',colors[i])
   .find(`[aria-label="Priority: ${priority}"]`).should('contain.text',priority);
 });
 cy.get('[aria-label^="Open details for TEST-1:"]').click();
 cy.get('[data-testid="issue-card-TEST-1"]').should('have.css','border-left-color',colors[0]);
});
